import os, re, json

sessions_dir = '/home/USER/runs/paper/qwen-h0c1-card/frozen/seen-reference-4/play/users/u079/system/state/sessions'
fpath = os.path.join(sessions_dir, '01a18a0f-bcf1-764a-b6c9-d4cd26a2e202.jsonl')

with open(fpath) as fp:
    content = fp.read()

# Extract all grids including demo pairs
pattern = r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n(.+?)(?=\n(Demo pair|\n))'

grids = {}
for m in re.finditer(pattern, content, re.DOTALL):
    group_id, h, w, grid_text = m.groups()
    if h != int(grid_text.strip().split('\n')[0].replace(',', '').strip()):
        grid_rows = [r.split() for r in grid_text.strip().split('\n')]
        valid_rows = []
        for row in grid_rows:
            if len(row) == w and all(x.isdigit() for x in row):
                valid_rows.append([int(x) for x in row])
        if valid_rows:
            grids[group_id] = valid_rows

print(f"Found {len(grids)} grids:")
for group_id in sorted(grids.keys()):
    grid = grids[group_id]
    print(f"\n{group_id} ({len(grid)}x{len(grid[0])}):")
    for row in grid:
        print(row)

